-- Curated beta dataset. Values are evidence-linked and intentionally narrow.
-- Immigration and cost facts require scheduled review; rankings are contextual only.

on conflict(canonical_url) do update set status=excluded.status,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at,verification_notes=excluded.verification_notes;

on conflict(code) do update set summary=excluded.summary,state=excluded.state,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at;

on conflict(country_code,slug) do update set monthly_cost_low=excluded.monthly_cost_low,monthly_cost_high=excluded.monthly_cost_high,state=excluded.state,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at;

on conflict(country_code,fact_key) do update set value=excluded.value,qualification=excluded.qualification,state=excluded.state,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at;

on conflict(slug) do update set official_name=excluded.official_name,summary=excluded.summary,state=excluded.state,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at;

select i.id,i.official_name || ' main campus',i.city_id,true,'published','2026-08-04','2026-11-04'
from public.institutions i where i.city_id is not null
on conflict(institution_id,name) do update set state=excluded.state,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at;

on conflict(institution_id,publisher,ranking_name,edition_year,subject) do nothing;

on conflict(institution_id,origin_country,study_level,qualification_pattern) do update set minimum_result=excluded.minimum_result,evaluation_state=excluded.evaluation_state,notes=excluded.notes,state=excluded.state,last_verified_at=excluded.last_verified_at,next_review_at=excluded.next_review_at;

on conflict do nothing;

