insert into public.countries(code,slug,name,flag_emoji,currency_code,currency_symbol,primary_language,student_route_name,visa_difficulty,visa_fee_amount,visa_fee_currency,proof_funds_amount,proof_funds_currency,proof_funds_period_months,work_hours_term,post_study_months,monthly_cost_low,monthly_cost_high,cost_currency,summary,healthcare_summary,work_summary,post_study_summary,climate_summary,community_summary,visa_uncertainty,state,last_verified_at,next_review_at)
values
('GB','united-kingdom','United Kingdom','🇬🇧','GBP','£','English','Student visa','moderate',558,'GBP',10539,'GBP',9,20,18,1171,2200,'GBP','Large programme market with clear sponsor and visa rules; cost varies sharply by city.','Student applicants normally pay the Immigration Health Surcharge and receive NHS access under its terms.','Degree-level students at eligible sponsors are normally limited to 20 hours per week during term.','The Graduate route is scheduled at 18 months for non-doctoral applications made from 1 January 2027; verify before planning.','Temperate and often wet, with mild summers and cool winters.','Major university cities have established Muslim and South Asian communities; proximity to facilities must be checked by postcode.','Rules and fees change frequently; CAS timing, financial evidence and course-specific ATAS needs can alter readiness.','published','2026-08-04','2026-09-04'),
('DE','germany','Germany','🇩🇪','EUR','€','German','National study visa / residence permit','moderate',75,'EUR',11904,'EUR',12,20,18,900,1200,'EUR','Strong public-university value with more programme and city variation than tuition headlines imply.','Compliant health insurance is mandatory for enrolment and residence purposes.','Students may generally work up to 140 full or 280 half days yearly, or up to 20 hours weekly under the current route.','Graduates can generally seek qualified employment for up to 18 months after study.','Four seasons; colder winters and regional variation between maritime and continental areas.','Large cities and university towns commonly provide mosques, halal options and international student societies; local availability varies.','Blocked-account levels and recognition steps change; programme language and degree equivalence remain institution-specific.','published','2026-08-04','2026-09-04'),
('NL','netherlands','Netherlands','🇳🇱','EUR','€','Dutch','Residence permit for study','moderate',254,'EUR',13569.24,'EUR',12,16,12,1000,1500,'EUR','English-taught options are strong, but housing scarcity materially affects feasibility.','Study-only students generally need adequate private or home-country cover; Dutch public insurance rules change when paid work begins.','Non-EU students can normally work up to 16 hours weekly or only in summer, with employer permit conditions.','Eligible graduates may apply for a one-year orientation permit.','Maritime climate with mild summers, cool winters, wind and frequent rain.','Amsterdam, Rotterdam, The Hague and major student cities have visible Muslim and South Asian communities; check commute and local facilities.','Recognised-sponsor status, annual study norm and housing availability are major dependencies.','published','2026-08-04','2026-09-04'),
('IE','ireland','Ireland','🇮🇪','EUR','€','English','Long Stay D study visa / Stamp 2','moderate',60,'EUR',10000,'EUR',12,20,24,1200,2250,'EUR','English-speaking study route with a smaller institution market and severe accommodation pressure in Dublin.','Private medical insurance is compulsory for non-EU/EEA students.','Stamp 2 students may normally work 20 hours weekly in term and 40 hours during specified vacations.','Level 9 or above graduates may receive up to 24 months under the Third Level Graduate Programme; Level 8 is normally 12 months.','Mild maritime climate with frequent rain, wind and limited temperature extremes.','Dublin and other university cities have active Muslim and South Asian communities; housing location determines practical access.','Visa finance, eligible-programme status, registration and accommodation availability must all be verified.','published','2026-08-04','2026-09-04')
insert into public.cities(country_code,slug,name,monthly_cost_low,monthly_cost_high,accommodation_low,accommodation_high,deposit_summary,transport_summary,safety_summary,climate_summary,community_summary,source_id,confidence,state,last_verified_at,next_review_at)
values
('GB','leeds','Leeds',862,1833,507,1300,'Private and university contract terms vary; confirm the exact refundable deposit before payment.','Walkable student areas with bus and rail links; budget separately for inter-city travel.','Use standard city precautions and institution safety services; no personal safety guarantee is implied.','Cool, wet winters and mild summers.','Established Muslim and South Asian communities with multiple halal and worship options; check distance from the chosen campus.',(select id from public.source_records where canonical_url='https://www.leeds.ac.uk/international-fees-costs/doc/living-expenses'),85,'published','2026-08-04','2026-11-04'),
('GB','london','London',1529,2600,900,1800,'Deposits and advance-rent requirements can materially increase arrival cash needs.','Extensive public transport but materially higher monthly travel costs.','Safety varies by neighbourhood and travel time; compare campus-to-home routes.','Mild but wet climate; urban heat can raise summer temperatures.','Large and diverse Muslim and South Asian communities across multiple boroughs.',(select id from public.source_records where canonical_url='https://www.gov.uk/student-visa/money'),60,'published','2026-08-04','2026-10-04'),
('GB','manchester','Manchester',1050,1900,550,1200,'Confirm whether utilities and council-tax exemptions are reflected in the contract.','Strong tram, bus and rail network; student-area commute varies.','Use university and local guidance when selecting neighbourhoods.','Cool, wet and often cloudy with mild summers.','Large Muslim and South Asian communities and broad halal availability.',(select id from public.source_records where canonical_url='https://www.gov.uk/student-visa/money'),55,'published','2026-08-04','2026-10-04'),
('DE','munich','Munich',1200,1700,300,1000,'Student-residence deposits can be lower than private-market deposits; TUM cites about €500 in one student programme.','Dense public transport; student tickets and the Deutschlandticket can reduce cost.','Generally well-served urban environment; use local guidance for neighbourhood-level decisions.','Cold winters and warm summers; Alpine weather changes can be rapid.','Established international and Muslim communities; halal access is broad but campus proximity varies.',(select id from public.source_records where canonical_url='https://www.international.tum.de/en/global/exchangestudents/general-information-for-international-students/preparing-your-stay/'),82,'published','2026-08-04','2026-11-04'),
('DE','saarbrucken','Saarbrücken',900,1150,300,600,'Confirm deposit and utilities directly with the housing provider.','Compact city with buses and regional rail; semester arrangements may cover some transport.','Use university and municipal guidance for current local conditions.','Cool winters, mild summers and year-round rainfall.','Smaller community than major German metros; verify halal and worship access relative to campus.',(select id from public.source_records where canonical_url='https://www.daad.de/en/studying-in-germany/living-in-germany/finances/'),60,'published','2026-08-04','2026-11-04'),
('NL','delft','Delft',1050,1550,450,1000,'Housing providers may require deposits and advance payments; never rely on an unverified listing.','Cycling is central; local bus and national rail connections are strong.','Cycle safety and housing scams are practical student risks; use institution-approved channels.','Mild, windy and wet maritime climate.','International student community with access to nearby Rotterdam and The Hague facilities.',(select id from public.source_records where canonical_url='https://www.studyinnl.org/finances/daily-student-expenses-and-cost-of-living-in-the-netherlands'),68,'published','2026-08-04','2026-11-04'),
('NL','amsterdam','Amsterdam',1300,1900,650,1250,'High demand increases scam and advance-payment risk; institution-supported housing should be prioritised.','Cycling and public transport are extensive but add recurring cost.','Housing fraud and cycle safety deserve explicit checks alongside normal city precautions.','Mild, windy and frequently wet.','Large diverse Muslim and South Asian communities with broad food and worship access.',(select id from public.source_records where canonical_url='https://www.studyinnl.org/finances/daily-student-expenses-and-cost-of-living-in-the-netherlands'),65,'published','2026-08-04','2026-11-04'),
('IE','dublin','Dublin',1754,2254,750,1333,'A deposit equivalent to one month’s rent is commonly required, with rent paid in advance.','Bus, rail and tram options are available; accommodation location drives commute cost.','Accommodation scams and late-night travel planning are material student considerations.','Mild, windy and rainy with limited temperature extremes.','Large international, Muslim and South Asian communities with broad halal and worship access.',(select id from public.source_records where canonical_url='https://www.tcd.ie/study/international/welcome/cost-of-living/'),88,'published','2026-08-04','2026-11-04'),
('IE','cork','Cork',1200,1800,650,1100,'A one-month refundable deposit is common; verify inventory and lease terms.','Bus-based local transport with a compact centre; housing distance affects commute.','Use institution accommodation services and standard urban precautions.','Mild and rainy maritime climate.','Active international community; Muslim and South Asian facilities exist but are less distributed than Dublin.',(select id from public.source_records where canonical_url='https://www.educationinireland.com/en/plan-your-study-abroad/student-accommodation'),58,'published','2026-08-04','2026-11-04')
